import { IonBackButton, IonButtons, IonContent, IonHeader, IonIcon, IonItem, IonLabel, IonList, IonPage, IonTitle, IonToolbar, alertController } from '@ionic/vue'; import { documentTextOutline, imagesOutline, shieldCheckmarkOutline } from 'ionicons/icons'; const version = import.meta.env.VITE_APP_VERSION || '1.0.0';
